func f(x) { return (x > 0) + 1 }
mut i := 0
mut caught := 0
while i < 200 { try { f(7) } except error { caught += 1 } i += 1 }
assert_equal(caught, 200)
print("PASS")

func f(x) { let r := x > 0 return r }
mut i := 0
while i < 200 { assert_equal(f(7), true) i += 1 }
print("PASS")

func f(x) { mut r := 0 if x > 0 { r = true } return r }
mut i := 0
while i < 200 { assert_equal(f(7), true) i += 1 }
print("PASS")

func f(x) { return x > 0 && x < 10 }
mut i := 0
while i < 200 { assert_equal(f(7), true) i += 1 }
print("PASS")

mut truth := true func f(x) { return truth }
mut i := 0
while i < 200 { assert_equal(f(7), true) i += 1 }
print("PASS")
